import 'package:drift/drift.dart';
import 'package:uuid/uuid.dart';

import '../database/app_database.dart';
import '../models/app_notification.dart';

/// Notification persistence and query gateway.
class NotificationRepository {
  NotificationRepository(this._database);

  final AppDatabase _database;
  final Uuid _uuid = Uuid();

  /// Adds an alert, skipping it when an unread alert with the same dedupe key
  /// already exists. Dedupe keeps low-stock and offline-sync noise manageable.
  Future<void> add({
    required String kind,
    required String title,
    required String message,
    NotificationSeverity severity = NotificationSeverity.info,
    String? entityType,
    String? entityId,
    String? dedupeKey,
  }) async {
    if (dedupeKey != null && dedupeKey.isNotEmpty) {
      final existing = await _database
          .customSelect(
            '''
              SELECT 1 AS found FROM app_notifications
              WHERE dedupe_key = ? AND is_read = 0
              LIMIT 1
            ''',
            variables: [Variable.withString(dedupeKey)],
          )
          .getSingleOrNull();
      if (existing != null) {
        return;
      }
    }

    await _database
        .into(_database.appNotifications)
        .insert(
          AppNotificationsCompanion.insert(
            id: _uuid.v4(),
            kind: kind,
            severity: Value(severity.name),
            title: title,
            message: message,
            entityType: Value(entityType),
            entityId: Value(entityId),
            dedupeKey: Value(dedupeKey),
            createdAt: DateTime.now().toUtc(),
          ),
        );
  }

  Future<List<AppNotification>> list({int limit = 100}) async {
    final rows = await _database
        .customSelect(
          '''
            SELECT id, kind, severity, title, message, entity_type, entity_id,
                   is_read, created_at
            FROM app_notifications
            ORDER BY created_at DESC
            LIMIT ?
          ''',
          variables: [Variable.withInt(limit.clamp(1, 500).toInt())],
        )
        .get();
    return rows.map(_map).toList(growable: false);
  }

  Stream<List<AppNotification>> watchRecent({int limit = 100}) {
    final query = _database.select(_database.appNotifications)
      ..orderBy([(table) => OrderingTerm.desc(table.createdAt)])
      ..limit(limit.clamp(1, 500).toInt());
    return query.watch().map(
      (rows) => rows.map(_mapRow).toList(growable: false),
    );
  }

  Future<int> unreadCount() async {
    final row = await _database.customSelect('''
            SELECT COUNT(*) AS unread
            FROM app_notifications
            WHERE is_read = 0
          ''').getSingle();
    return row.read<int>('unread');
  }

  Future<void> markRead(String id) async {
    await (_database.update(
      _database.appNotifications,
    )..where((table) => table.id.equals(id))).write(
      AppNotificationsCompanion(
        isRead: const Value(true),
        readAt: Value(DateTime.now().toUtc()),
      ),
    );
  }

  Future<void> markAllRead() async {
    await _database.customStatement(
      'UPDATE app_notifications SET is_read = 1, read_at = ? WHERE is_read = 0',
      [DateTime.now().toUtc().millisecondsSinceEpoch ~/ 1000],
    );
  }

  Future<void> clearRead() async {
    await _database.customStatement(
      'DELETE FROM app_notifications WHERE is_read = 1',
    );
  }

  AppNotification _map(QueryRow row) {
    return AppNotification(
      id: row.read<String>('id'),
      kind: row.read<String>('kind'),
      severity: NotificationSeverity.fromWire(row.read<String>('severity')),
      title: row.read<String>('title'),
      message: row.read<String>('message'),
      entityType: row.readNullable<String>('entity_type'),
      entityId: row.readNullable<String>('entity_id'),
      isRead: row.read<int>('is_read') != 0,
      createdAt: DateTime.fromMillisecondsSinceEpoch(
        row.read<int>('created_at') * 1000,
        isUtc: true,
      ),
    );
  }

  AppNotification _mapRow(AppNotificationRow row) {
    return AppNotification(
      id: row.id,
      kind: row.kind,
      severity: NotificationSeverity.fromWire(row.severity),
      title: row.title,
      message: row.message,
      entityType: row.entityType,
      entityId: row.entityId,
      isRead: row.isRead,
      createdAt: row.createdAt,
    );
  }
}
